                            .showToast({
                            body: {
                                title: "Memory Restored",
                                message: `${memoriesResult.results.length} memories injected after compaction`,
                                variant: "success",
                                duration: 3000,
                            },
                        })
                            .catch(() => { });
                    }
                    log("Compaction memory injected", {
                        sessionID,
                        count: memoriesResult.results.length,
                    });
                }
