function formatMemoriesForCompaction(memories) {
    let output = `## Restored Session Memory\n\n`;
    memories.forEach((m, i) => {
        output += `### Memory ${i + 1}\n`;
        output += `${m.memory}\n\n`;
        if (m.tags && m.tags.length > 0) {
            output += `Tags: ${m.tags.join(", ")}\n\n`;
        }
    });
    return output;
}

